1	#!/usr/bin/env node
2	/**
3	 * 200-conversation grounding test: fine-tuned model vs Gemini vs base.
4	 * Measures: invented numbers, placeholder validity, rewrite rate, latency.
5	 * Usage: node words/grounding-test.js
6	 * Needs: MODEL_URL, GEMINI_API_KEY in env or .env
7	 */
8	
9	import { simulate } from "../sim/engine.js";
10	import { fillPlaceholders } from "../sim/facts.js";
11	import { checkSentence, writeReply } from "../voice/chat.js";
12	import { readFileSync } from "fs";
13	
14	try {
15	  const env = readFileSync(".env", "utf8");
16	  for (const line of env.split("\n")) {
17	    const m = line.match(/^([A-Z_]+)=(.+)$/);
18	    if (m && !process.env[m[1]]) process.env[m[1]] = m[2];
19	  }
20	} catch {}
21	
22	const MODEL_URL = process.env.MODEL_URL;
23	const GEMINI_KEY = process.env.GEMINI_API_KEY;
24	
25	const NAMES = ["Ethan", "Sarah", "Marcus", "Priya", "James", "Olivia", "Wei", "Aisha", "Carlos", "Emma",
26	  "Noah", "Fatima", "Liam", "Yuki", "Ava", "Omar", "Chloe", "Raj", "Mia", "Jamal"];
27	const QUESTIONS = [
28	  "Did I end up okay with money?",
29	  "How much did I save by the time I was seventy?",
30	  "Was I healthy?",
31	  "Did I retire comfortably?",
32	  "What's the one thing I should change?",
33	  "How long did I live?",
34	  "Did my savings last?",
35	  "Was I able to travel?",
36	  "Did I have enough for retirement?",
37	  "What would you tell me about my health?",
38	  "Should I save more?",
39	  "How are my healthy years looking?",
40	  "Did exercise make a difference?",
41	  "What about my income in retirement?",
42	  "Any regrets about money?",
43	  "Was quitting smoking worth it?",
44	  "Did I ever run out of money?",
45	  "How did my habits affect me?",
46	  "What's the best financial decision I made?",
47	  "Tell me about my future.",
48	];
49	
50	function randInt(lo, hi) { return lo + Math.floor(Math.random() * (hi - lo + 1)); }
51	function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
52	
53	function randomProfile() {
54	  return {
55	    name: pick(NAMES),
56	    age: randInt(18, 35),
57	    sex: Math.random() < 0.5 ? "male" : "female",
58	    province: "ON",
59	    income_per_year: randInt(20000, 120000),
60	    savings: { tfsa: randInt(0, 20000), rrsp: randInt(0, 15000), other: randInt(0, 5000) },
61	    saving_per_month: randInt(0, 500),
62	    retirement_age: randInt(60, 70),
63	    habits: {
64	      exercise_per_week: randInt(0, 7),
65	      sleep_hours: randInt(4, 9),
66	      smoker: Math.random() < 0.2,
67	      drinks_per_week: randInt(0, 15),
68	    },
69	  };
70	}
71	
72	function gradeReply(sentences, facts) {
73	  let good = 0, bad = 0, rewrite = 0;
74	  for (const s of sentences) {
75	    if (checkSentence(s, facts)) {
76	      const filled = fillPlaceholders(s, facts);
77	      if (filled.ok) good++;
78	      else bad++;
79	    } else {
80	      bad++;
81	      rewrite++;
82	    }
83	  }
84	  return { good, bad, rewrite, total: sentences.length };
85	}
86	
87	async function callFineTuned(question, facts, name) {
88	  if (!MODEL_URL) return null;
89	  const keys = Object.keys(flattenFacts(facts));
90	  const start = Date.now();
91	  const res = await fetch(`${MODEL_URL}/chat/completions`, {
92	    method: "POST",
93	    signal: AbortSignal.timeout(8000),
94	    headers: { "content-type": "application/json" },
95	    body: JSON.stringify({
96	      messages: [
97	        { role: "system", content: `You are ${name} at age 70. Reply warmly in 1-3 sentences. Never write any digit or number word. Use only these placeholders: ${keys.map(k => `{${k}}`).join(", ")}. Reply as JSON: {"sentences": ["...", "..."]}` },
98	        { role: "user", content: question },
99	      ],
100	      temperature: 0.7,
101	      max_tokens: 300,
102	    }),
103	  });
104	  const latency = Date.now() - start;
105	  const body = await res.json();
106	  const text = body?.choices?.[0]?.message?.content ?? "";
107	  let sentences;
108	  try { sentences = JSON.parse(text).sentences; } catch {}
109	  if (!Array.isArray(sentences)) sentences = text.split(/(?<=[.!?])\s+/).filter(Boolean).slice(0, 4);
110	  return { sentences: sentences.map(String), latency };
111	}
112	
113	function flattenFacts(facts) {
114	  const out = {};
115	  const walk = (obj, prefix) => {
116	    for (const [k, v] of Object.entries(obj ?? {})) {
117	      if (k === "sources") continue;
118	      const path = prefix ? `${prefix}.${k}` : k;
119	      if (v && typeof v === "object" && !Array.isArray(v)) walk(v, path);
120	      else if (typeof v === "number" || typeof v === "string") out[path] = v;
121	    }
122	  };
123	  walk(facts, "");
124	  return out;
125	}
126	
127	async function callGemini(question, facts, name) {
128	  if (!GEMINI_KEY) return null;
129	  const start = Date.now();
130	  const sentences = await writeReply({
131	    question, facts, name,
132	    apiKey: GEMINI_KEY,
133	    timeoutMs: 8000,
134	  });
135	  return { sentences, latency: Date.now() - start };
136	}
137	
138	async function main() {
139	  const N = 200;
140	  const results = { finetune: { pass: 0, fail: 0, rewrites: 0, total: 0, latencies: [] },
141	                    gemini:   { pass: 0, fail: 0, rewrites: 0, total: 0, latencies: [] } };
142	
143	  console.log(`Running ${N} conversations...`);
144	  for (let i = 0; i < N; i++) {
145	    const profile = randomProfile();
146	    const facts = simulate(profile);
147	    const question = pick(QUESTIONS);
148	
149	    // Fine-tuned model
150	    if (MODEL_URL) {
151	      try {
152	        const r = await callFineTuned(question, facts, profile.name);
153	        if (r) {
154	          const g = gradeReply(r.sentences, facts);
155	          results.finetune.pass += g.good;
156	          results.finetune.fail += g.bad;
157	          results.finetune.rewrites += g.rewrite;
158	          results.finetune.total += g.total;
159	          results.finetune.latencies.push(r.latency);
160	        }
161	      } catch (e) { results.finetune.fail++; results.finetune.total++; }
162	    }
163	
164	    // Gemini
165	    if (GEMINI_KEY) {
166	      try {
167	        const r = await callGemini(question, facts, profile.name);
168	        if (r) {
169	          const g = gradeReply(r.sentences, facts);
170	          results.gemini.pass += g.good;
171	          results.gemini.fail += g.bad;
172	          results.gemini.rewrites += g.rewrite;
173	          results.gemini.total += g.total;
174	          results.gemini.latencies.push(r.latency);
175	        }
176	      } catch (e) { results.gemini.fail++; results.gemini.total++; }
177	    }
178	
179	    if ((i + 1) % 20 === 0) process.stdout.write(`  ${i + 1}/${N}\n`);
180	  }
181	
182	  console.log("\n=== GROUNDING TEST RESULTS (200 conversations) ===\n");
183	
184	  for (const [label, r] of [["Fine-tuned", results.finetune], ["Gemini", results.gemini]]) {
185	    if (r.total === 0) { console.log(`${label}: skipped (no key/url)`); continue; }
186	    const passRate = ((r.pass / r.total) * 100).toFixed(1);
187	    const rewriteRate = ((r.rewrites / r.total) * 100).toFixed(1);
188	    const sorted = r.latencies.slice().sort((a, b) => a - b);
189	    const median = sorted[Math.floor(sorted.length / 2)] || 0;
190	    const p95 = sorted[Math.floor(sorted.length * 0.95)] || 0;
191	    console.log(`${label}:`);
192	    console.log(`  Sentences with zero invented numbers: ${r.pass}/${r.total} (${passRate}%)`);
193	    console.log(`  Sentences needing rewrite: ${r.rewrites}/${r.total} (${rewriteRate}%)`);
194	    console.log(`  Latency median: ${median} ms, p95: ${p95} ms`);
195	    console.log();
196	  }
197	}
198	
199	main().catch(console.error);
