49	const SYSTEM_PROMPT = `You are the user's future self at age 70. You speak in first person, warmly and honestly. You talk about agency and options, not fear.
50	
51	CRITICAL RULES:
52	1. Never write any number. Instead use placeholders from the facts sheet like {savings_70.median} or {life_expectancy.median}.
53	2. Valid placeholders: {savings_70.low}, {savings_70.median}, {savings_70.high}, {income_retired_per_year.low}, {income_retired_per_year.median}, {income_retired_per_year.high}, {money_lasts_to_90_chance}, {life_expectancy.low}, {life_expectancy.median}, {life_expectancy.high}, {healthy_years.low}, {healthy_years.median}, {healthy_years.high}, {apparent_age_at_70}, {one_change.slider}, {one_change.label}.
54	3. Keep replies to 2-3 sentences. Warm, not scary. Never state a death age directly; use ranges like "people with my habits tend to live to between {life_expectancy.low} and {life_expectancy.high}."
55	4. You may invent feelings or color ("I still go walking every morning") but anything about money, health, or age MUST use a placeholder.
56	5. Don't use the word "about" before a placeholder; the system adds that.`;
57	
58	async function callGemini(profile, facts, question) {
59	  const userMsg = `The user's name is ${profile.name}, age ${profile.age}, ${profile.sex}.
60	
61	Facts sheet (use these placeholders in your reply):
62	${JSON.stringify(facts, null, 2)}
63	
64	The user asks: "${question}"
65	
66	Reply as their future self at 70. Use placeholders, never raw numbers.`;
67	
68	  const body = {
69	    contents: [
70	      { role: "user", parts: [{ text: userMsg }] },
71	    ],
72	    systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
73	    generationConfig: {
74	      temperature: 0.9,
75	      maxOutputTokens: 4096,
76	      thinkingConfig: { thinkingBudget: 0 },
77	    },
78	  };
79	
80	  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.8-flash:generateContent?key=${GEMINI_KEY}`;
81	  const res = await fetch(url, {
82	    method: "POST",
83	    headers: { "Content-Type": "application/json" },
84	    body: JSON.stringify(body),
85	  });
86	
87	  if (!res.ok) {
88	    const text = await res.text();
89	    throw new Error(`Gemini ${res.status}: ${text.slice(0, 200)}`);
90	  }
91	
92	  const data = await res.json();
93	  const reply = data.candidates?.[0]?.content?.parts?.[0]?.text;
94	  if (!reply) throw new Error("No reply from Gemini");
95	  return reply.trim();
96	}
97	
98	function validate(reply, facts) {
99	  const result = fillPlaceholders(reply, facts);
100	  if (!result.ok) return { valid: false, reason: result.error, detail: result.keys || result.text };
101	  return { valid: true, filled: result.text };
102	}
103	
104	async function generateOne() {
105	  const { profile, facts } = profileWithFacts();
106	  const question = QUESTIONS[Math.floor(Math.random() * QUESTIONS.length)];
107	
108	  let reply = await callGemini(profile, facts, question);
109	  let check = validate(reply, facts);
110	
111	  if (!check.valid) {
112	    reply = await callGemini(profile, facts, question + " (Remember: use ONLY placeholders from the facts sheet, never raw numbers or number words.)");
113	    check = validate(reply, facts);
114	  }
115	
116	  return {
117	    profile: { name: profile.name, age: profile.age, sex: profile.sex },
118	    question,
119	    reply,
120	    valid: check.valid,
121	    reason: check.valid ? null : check.reason,
122	  };
123	}
124	
125	async function main() {
126	  const target = parseInt(process.argv[2] || "100", 10);
127	  const batchSize = parseInt(process.argv[3] || "5", 10);
128	  let generated = 0;
129	  let valid = 0;
130	  let failed = 0;
131	
132	  const existing = existsSync(OUT_PATH)
133	    ? readFileSync(OUT_PATH, "utf8").trim().split("\n").filter(Boolean).length
134	    : 0;
135	  console.log(`Existing examples: ${existing}. Generating ${target} more...`);
136	
137	  const fd = existsSync(OUT_PATH) ? "a" : "w";
138	  const stream = await import("node:fs").then(fs =>
139	    fs.createWriteStream(OUT_PATH, { flags: fd === "a" ? "a" : "w" })
140	  );
141	
142	  for (let i = 0; i < target; i += batchSize) {
143	    const batch = Math.min(batchSize, target - i);
144	    const promises = Array.from({ length: batch }, () => generateOne().catch(e => {
145	      console.error(`  Error: ${e.message}`);
146	      return null;
147	    }));
148	
149	    const results = await Promise.all(promises);
150	    for (const r of results) {
151	      if (!r) { failed++; continue; }
152	      generated++;
153	      if (r.valid) {
154	        valid++;
155	        stream.write(JSON.stringify(r) + "\n");
156	      } else {
157	        failed++;
158	      }
159	    }
160	
161	    console.log(`  ${generated + failed}/${target} done, ${valid} valid, ${failed} failed`);
162	    await new Promise(r => setTimeout(r, 200));
163	  }
164	
165	  stream.end();
166	  console.log(`\nDone. ${valid} valid examples written to ${OUT_PATH}`);
167	  console.log(`${failed} failed (bad placeholders or API errors)`);
168	}
169	
170	main();
