110	export async function fetchRates() {
111	  const rates = { ...HARDCODED_FALLBACK };
112	  const errors = [];
113	
114	  const fetchers = [
115	    { key: "cpp_max_monthly", fn: fetchCPP, label: "CPP" },
116	    { key: "oas_max_monthly", fn: fetchOAS, label: "OAS" },
117	    { key: "tfsa_annual_limit", fn: fetchTFSA, label: "TFSA" },
118	    { key: "rrsp_annual_max", fn: fetchRRSP, label: "RRSP" },
119	  ];
120	
121	  const results = await Promise.allSettled(fetchers.map(f => f.fn()));
122	  for (let i = 0; i < fetchers.length; i++) {
123	    const { key, label } = fetchers[i];
124	    const result = results[i];
125	    if (result.status === "fulfilled" && result.value !== null) {
126	      const [lo, hi] = BOUNDS[key] || [0, Infinity];
127	      if (result.value >= lo && result.value <= hi) {
128	        rates[key] = result.value;
129	      } else {
130	        errors.push(`${label}: fetched ${result.value} outside bounds [${lo}, ${hi}], using fallback ${rates[key]}`);
131	      }
132	    } else {
133	      const reason = result.status === "rejected" ? result.reason.message : "pattern not found";
134	      errors.push(`${label}: ${reason}, using fallback ${rates[key]}`);
135	    }
136	  }
137	
138	  rates.fetched_at = new Date().toISOString();
139	  rates.sources = SOURCES;
140	  if (errors.length > 0) rates.fetch_errors = errors;
141	
142	  writeFileSync(RATES_PATH, JSON.stringify(rates, null, 2));
143	  return { rates, errors };
144	}
